  const b = g.append('rect').attr('x', labW).attr('y', 6).attr('height', 12).attr('rx', 4).style('fill', (r) => r.pct < 0.6 ? 'var(--cds-chart-status-critical)' : r.pct < 0.85 ? 'var(--color-warn)' : 'var(--po-accent)').attr('data-source', 'conf_resumo').attr('data-field', 'pct').attr('data-where', (r) => WHERE() + '&chave=' + r.chave);
