  if (o.pago_fonte) { const d = el('div'); d.style.gridColumn = '1 / -1'; const dd = el('dd', 'muted', o.pago_fonte); dd.dataset.source = 'obras'; dd.dataset.field = 'pago_fonte'; dd.dataset.where = 'id=' + ENC(r.id); d.append(el('dt', null, 'Origem do valor pago'), dd); dl.append(d); }
